52	// decodeArgs unmarshals a call's arguments into dst, returning a model-facing
53	// message on failure.
54	func decodeArgs(tc llm.ToolCall, dst any) string {
55		if strings.TrimSpace(tc.Arguments) == "" {
56			return "" // no arguments is legitimate for tools whose fields are optional
57		}
58		if err := json.Unmarshal([]byte(tc.Arguments), dst); err != nil {
59			return fmt.Sprintf("The arguments were not valid JSON: %v", err)
60		}
61		return ""
62	}
